{
  "findings": [
    {
      "check_id": "CKV_AWS_79",
      "title": "Instance Metadata Service Version 1 is not disabled",
      "resource": "aws_launch_template.web_app",
      "severity": "MEDIUM",
      "explanation": "The launch template does not configure the metadata options to require IMDSv2 (HTTP tokens). This allows instances to be vulnerable to SSRF attacks that can retrieve temporary credentials from the instance metadata service without a token."
    },
    {
      "check_id": "UNKNOWN",
      "title": "Hardcoded secrets in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The 'user_data' block contains a hardcoded API key ('sk-1234567890abcdef') and exports a database password. Hardcoding secrets in Terraform code or user data exposes them in state files, version control, and potentially via the instance metadata if not properly protected."
    }
  ],
  "patched_code": "resource "aws_launch_template" "web_app" {
  name_prefix   = "automated-employee-onboarding-platform-lt-web-"
  image_id      = data.aws_ami.ubuntu.id
  instance_type = var.instance_type
  key_name      = var.key_pair_name
  vpc_security_group_ids = [aws_security_group.web_app.id]

  metadata_options {
    http_endpoint = "enabled"
    http_tokens   = "required"
  }

  user_data = base64encode(<<-EOF
              export DATABASE_PASSWORD="${var.db_password}"
              # WARNING: Do not hardcode API keys. Use AWS Secrets Manager or SSM Parameter Store.
              apt-get update
              apt-get install -y nginx nodejs npm
              systemctl start nginx
              systemctl enable nginx
              EOF
  )
  tag_specifications {
    resource_type = "instance"
  }
}",
  "fix_summary": "Added `metadata_options` block with `http_tokens = "required"` to enforce IMDSv2 and mitigate SSRF risks. Removed the hardcoded API key from `user_data` as it constitutes a critical secret exposure; replaced it with a comment indicating secure alternatives should be used."
}
